<div class="page-heading"><h1>Pendaftaran Saya</h1><p>Pantau verifikasi, informasi biaya, dan arahan admin untuk setiap pendaftaran.</p></div>
<?php $registrations=rows('SELECT r.*,b.start_date,b.end_date,b.delivery_format,p.title,s.payment_instructions FROM registrations r JOIN training_batches b ON b.id=r.batch_id JOIN training_programs p ON p.slug=b.program_slug LEFT JOIN batch_settings s ON s.batch_id=b.id WHERE r.user_id=? ORDER BY r.created_at DESC',[$uid]);if(!$registrations)emptyState('Belum ada pendaftaran','Daftar pada batch resmi melalui halaman jadwal. Daftar minat sebelumnya merupakan permintaan kontak, bukan pendaftaran kelas.','public-training.php','Lihat jadwal'); ?>
<div class="stack"><?php foreach($registrations as $registration): ?><article class="panel" id="registration-<?= (int)$registration['id'] ?>"><div class="row"><span class="muted">REG-<?= str_pad((string)$registration['id'],6,'0',STR_PAD_LEFT) ?> · <?= e($registration['created_at']) ?></span><span class="badge <?= e($registration['status']) ?>"><?= e(statusText($registration['status'])) ?></span></div><h2 style="margin-top:20px"><?= e($registration['title']) ?></h2><dl class="meta-list"><div><dt>Periode</dt><dd><?= e($registration['start_date'].' — '.$registration['end_date']) ?></dd></div><div><dt>Biaya pendaftaran</dt><dd><?= e(rupiah($registration['price'])) ?></dd></div><div><dt>Status pembayaran</dt><dd><?= e(statusText($registration['payment_status'])) ?></dd></div><div><dt>Metode</dt><dd><?= e($registration['delivery_format']) ?></dd></div></dl><p class="notice info"><?= e($registration['admin_remarks']?:'Admin belum memberikan catatan. Tunggu pemberitahuan verifikasi di portal ini.') ?></p><?php if((float)$registration['price']>0): ?><p class="muted"><?= nl2br(e($registration['payment_instructions']?:'Instruksi pembayaran belum diterbitkan. Hubungi admin sebelum melakukan pembayaran.')) ?></p><?php endif; ?><div class="actions"><?php if($registration['status']==='approved'): ?><a class="btn" href="portal.php?view=learning&amp;batch=<?= (int)$registration['batch_id'] ?>">Buka pelatihan</a><?php elseif(in_array($registration['status'],['pending','under_review'],true)): ?><form method="post" data-busy-form><?= actionFields('cancel',(int)$registration['id']) ?><button type="submit" class="btn secondary">Batalkan pendaftaran ini</button></form><?php endif; ?><a class="btn secondary" href="contact.php">Hubungi admin</a></div></article><?php endforeach; ?></div>
